def traj(spec):
    """spec: dict week-number -> (P, Po, Pol). Missing weeks = None (not observed)."""
    return [list(spec[i]) if i in spec else None for i in range(1, 9)]

def rng(a, b, v):
    return {i: v for i in range(a, b + 1)}

